import math
from fractions import Fraction
from pymatgen.core import Structure
from pymatgen.symmetry.analyzer import SpacegroupAnalyzer
from typing import Any

def to_rational_string(val):
    val = float(val) % 1.0
    if abs(val - 1.0) < 1e-6:
        val = 0.0
    f = Fraction(val).limit_denominator(12)
    if f.numerator == 0 or f.numerator == f.denominator:
        return "0"
    return f"{f.numerator}/{f.denominator}"

def analyze_wyckoff_position_multiplicities_and_coordinates(filepath: str) -> dict[str, Any]:
    struct = Structure.from_file(filepath)
    sga = SpacegroupAnalyzer(struct, symprec=0.01)
    sym_struct = sga.get_symmetrized_structure()

    wyckoff_multiplicity_dict = {}
    wyckoff_coordinates_dict = {}

    for i, orbit in enumerate(sym_struct.equivalent_sites):
        symbol = sym_struct.wyckoff_symbols[i]
        letter = symbol[-1]
        multiplicity = int(symbol[:-1])

        if letter not in wyckoff_multiplicity_dict:
            wyckoff_multiplicity_dict[letter] = multiplicity
            coords = orbit[0].frac_coords
            wyckoff_coordinates_dict[letter] = [to_rational_string(c) for c in coords]

    # Sort dictionaries by key
    wyckoff_multiplicity_dict = dict(sorted(wyckoff_multiplicity_dict.items()))
    wyckoff_coordinates_dict = dict(sorted(wyckoff_coordinates_dict.items()))

    return {
        "wyckoff_multiplicity_dict": wyckoff_multiplicity_dict,
        "wyckoff_coordinates_dict": wyckoff_coordinates_dict
    }

if __name__ == "__main__":
    import json
    files = ["/root/cif_files/FeS2_mp-226.cif", "/root/cif_files/Al2O3_mp-7048.cif"]
    for f in files:
        print(f"File: {f}")
        try:
            result = analyze_wyckoff_position_multiplicities_and_coordinates(f)
            print(json.dumps(result, indent=4))
        except Exception as e:
            print(f"Error: {e}")

